import React, { useEffect, useState, useCallback } from 'react';
import { View, Text, Image, ScrollView, TouchableOpacity, ActivityIndicator, ToastAndroid } from 'react-native';
import LinearGradient from 'react-native-linear-gradient';
import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';
import { useNavigation, useFocusEffect } from '@react-navigation/native';
import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';
import { Colors } from '../../constants/Colors';
import { styles } from './styles';
import LeagueHeader from './LeagueHeader';
import DepartmentProgressList from '../components/DepartmentProgressList';
import { MMKV } from 'react-native-mmkv';
import { useDispatch, useSelector } from 'react-redux';
import { loadCaseById, setUserId, setCaseData, setSelectedTests, setSelectedDiagnosis, setSelectedTreatments, clearCurrentGame, setGameplay } from '../store/slices/currentGameSlice';
import { loadTodaysChallenge, selectCurrentChallenge, selectIsChallengeLoading, selectHasChallengeError, selectChallengeError } from '../store/slices/dailyChallengeSlice';
import { fetchCategories } from '../store/slices/categoriesSlice';
import departmentIcon from '../../constants/department.png';
import calendarIcon from '../../constants/calendar.png';
import { API_BASE } from '../../constants/Api';
import CloudBottom from '../components/CloudBottom';
import { useResponsive } from '../hooks/useResponsive';
import { Skeleton } from '../components/Skeleton';
import LifetimeOfferCard from '../components/LifetimeOfferCard';
import { useTranslation } from 'react-i18next';
import { trackEvent } from '../services/analytics';
import { hasReachedFreeCaseLimit } from '../services/caseAccess';
import { getCurrentLifetimeOfferStart } from '../services/lifetimeOffer';

export default function HomeScreen() {
  const themeColors = Colors.light;
  const navigation = useNavigation();
  const insets = useSafeAreaInsets();
  const { isTablet } = useResponsive();
  const { status: categoriesLoading, error: categoriesError } = useSelector(state => state.categories);
  const { userData, isPremium } = useSelector(state => state.user);
  const isFreeCaseLimitReached = !isPremium && hasReachedFreeCaseLimit(userData);
  const { t } = useTranslation();
  const [currentUserId, setCurrentUserId] = useState(undefined);
  const [isDailyChallengeLoading, setIsDailyChallengeLoading] = useState(false);
  const [isDailyChallengeCompleted, setIsDailyChallengeCompleted] = useState(false);
  const [isCheckingCompletion, setIsCheckingCompletion] = useState(true); // Start as true to show skeleton initially
  // MMKV storage instance for persisting suggested case
  const storage = React.useMemo(() => new MMKV(), []);

  // Lifetime offer card state — read from MMKV
  const [offerStartTime, setOfferStartTime] = useState(() => {
    try {
      const mmkv = new MMKV();
      const storedStart = mmkv.getNumber('lifetimeOfferStartTime') || 0;
      const startTime = getCurrentLifetimeOfferStart(storedStart);
      const wasDismissed = mmkv.getBoolean('lifetimeOfferDismissed');
      if (startTime && wasDismissed) {
        if (startTime !== storedStart) {
          mmkv.set('lifetimeOfferStartTime', startTime);
        }
        return startTime;
      }
      return null;
    } catch { return null; }
  });

  // Listen for MMKV changes so the card appears instantly when the modal is dismissed
  useEffect(() => {
    const listener = storage.addOnValueChangedListener((changedKey) => {
      if (changedKey !== 'lifetimeOfferDismissed') return;
      try {
        const storedStart = storage.getNumber('lifetimeOfferStartTime') || 0;
        const startTime = getCurrentLifetimeOfferStart(storedStart);
        const wasDismissed = storage.getBoolean('lifetimeOfferDismissed');
        // Only react when modal is dismissed (show card), don't hide when banner reopens
        if (startTime && wasDismissed) {
          if (startTime !== storedStart) {
            storage.set('lifetimeOfferStartTime', startTime);
          }
          setOfferStartTime(startTime);
        }
      } catch {}
    });
    return () => { try { listener?.remove?.(); } catch {} };
  }, [storage]);

  const handleOfferExpired = useCallback(() => {
    const startTime = Date.now();
    try {
      storage.set('lifetimeOfferStartTime', startTime);
    } catch {}
    setOfferStartTime(startTime);
  }, [storage]);

  // Responsive image height: 300 for iPad/tablet, 200 for iPhone/mobile
  const imageHeight = isTablet ? 350 : 200;

  // 1 hour expiration in milliseconds
  const SUGGESTED_CASE_EXPIRY_MS = 60 * 60 * 1000; // 1 hour

  // Load persisted suggested case SYNCHRONOUSLY to prevent race condition
  // Also check if the case has expired (1 hour)
  const [suggestedNextCase, setSuggestedNextCase] = useState(() => {
    try {
      const mmkv = new MMKV();
      const persistedCase = mmkv.getString('suggestedNextCase');
      if (persistedCase) {
        const parsed = JSON.parse(persistedCase);

        // Check if the case has expired (1 hour)
        const savedAt = parsed.savedAt || 0;
        const now = Date.now();
        const elapsed = now - savedAt;

        if (elapsed > SUGGESTED_CASE_EXPIRY_MS) {
          mmkv.delete('suggestedNextCase');
          return null;
        }

        return parsed;
      }
    } catch (error) {
      console.warn('Error loading persisted suggested case:', error);
    }
    return null;
  });

  const dispatch = useDispatch();

  // Progress selector for getting next case from departments
  const { status: progressStatus, items: departmentProgress } = useSelector(state => state.progress);

  // Daily challenge selectors
  const currentChallenge = useSelector(selectCurrentChallenge);
  const isChallengeLoading = useSelector(selectIsChallengeLoading);
  const hasChallengeError = useSelector(selectHasChallengeError);
  const challengeError = useSelector(selectChallengeError);

  useEffect(() => {
    try {
      const stored = storage.getString('user');
      if (stored) {
        const u = JSON.parse(stored);
        const uid = u?.userId || u?._id || u?.id;
        if (uid) {
          setCurrentUserId(uid);
          dispatch(setUserId(uid));
        }
      }
    } catch (_) { }
  }, [dispatch, storage]);

  useEffect(() => {
    if (categoriesLoading === 'idle') {
      dispatch(fetchCategories());
    }
  }, [categoriesLoading, dispatch]);

  // Load today's daily challenge on component mount
  useEffect(() => {
    dispatch(loadTodaysChallenge());
  }, [dispatch]);

  // Check if daily challenge is completed and get suggested next case
  useEffect(() => {
    const checkDailyChallengeCompletion = async () => {
      // If no challenge or user, stop checking and show appropriate UI
      if (!currentChallenge?._id || !currentUserId) {
        // Only stop checking if challenge has finished loading
        if (!isChallengeLoading) {
          setIsCheckingCompletion(false);
        }
        return;
      }

      setIsCheckingCompletion(true);

      try {
        const res = await fetch(
          `${API_BASE}/api/gameplays?userId=${encodeURIComponent(currentUserId)}&dailyChallengeId=${encodeURIComponent(currentChallenge._id)}&sourceType=dailyChallenge`
        );

        if (!res.ok) {
          setIsCheckingCompletion(false);
          return;
        }

        const data = await res.json();
        const gameplays = data?.gameplays || [];
        const completedGameplay = gameplays.find(gp => gp.status === 'completed');

        setIsDailyChallengeCompleted(!!completedGameplay);
      } catch (error) {
        console.warn('Error checking daily challenge completion:', error);
      } finally {
        setIsCheckingCompletion(false);
      }
    };

    checkDailyChallengeCompletion();
  }, [currentChallenge, currentUserId, isChallengeLoading]);

  // Get a random next case from departments when:
  // 1. Daily challenge is completed, OR
  // 2. No challenge available (API succeeded with null challenge), OR
  // 3. Challenge loading failed (meaning no challenge for today)
  const challengeStatus = useSelector(state => state.dailyChallenge.status);
  const isDailyChallengeUnavailableError = hasChallengeError
    && typeof challengeError === 'string'
    && /no daily challenge|no challenge/i.test(challengeError);
  const noDailyChallengeAvailable = (challengeStatus === 'succeeded' && !currentChallenge) || isDailyChallengeUnavailableError;
  // Only show suggested case when daily challenge is completed or no challenge available
  const shouldShowSuggestedCase = isDailyChallengeCompleted || (noDailyChallengeAvailable || hasChallengeError);
  const shouldShowDailyChallengeCard = isChallengeLoading
    || isCheckingCompletion
    || (hasChallengeError && !isDailyChallengeUnavailableError)
    || !!currentChallenge;

  // Pick a random suggested case only if we don't have one persisted
  useEffect(() => {

    // Skip if we already have a suggested case (from persistence or previous pick)
    if (suggestedNextCase) {
      return;
    }

    if (shouldShowSuggestedCase && progressStatus === 'succeeded' && Array.isArray(departmentProgress)) {
      // Step 1: Filter departments that have unsolved cases
      const deptsWithAnyCases = departmentProgress.filter(
        dept => Array.isArray(dept.unsolvedCases) && dept.unsolvedCases.length > 0
      );

      if (deptsWithAnyCases.length > 0) {
        let deptsWithSuggestions = deptsWithAnyCases;
        let pickingPremiumFallback = false;

        if (!isPremium) {
          const deptsWithFreeCases = deptsWithAnyCases.filter(dept =>
            dept.unsolvedCases.some(c => c.originalIndex < 2)
          );

          if (deptsWithFreeCases.length > 0) {
            deptsWithSuggestions = deptsWithFreeCases;
          } else {
            pickingPremiumFallback = true;
          }
        }

        // Pick a random department from available suggestions
        const randomDept = deptsWithSuggestions[Math.floor(Math.random() * deptsWithSuggestions.length)];

        const nextCase = !isPremium && !pickingPremiumFallback
          ? randomDept.unsolvedCases.find(c => c.originalIndex < 2)
          : randomDept.unsolvedCases[0];

        if (nextCase) {
          const newSuggestedCase = {
            caseId: nextCase.caseId,
            caseTitle: nextCase.caseTitle || 'Medical Case',
            mainimage: nextCase.mainimage || null,
            departmentName: randomDept.name || 'Department',
            isPremiumCase: !isPremium
              && (nextCase.originalIndex >= 2 || pickingPremiumFallback),
            savedAt: Date.now(), // Timestamp for expiration
          };

          setSuggestedNextCase(newSuggestedCase);

          // Persist the suggested case to MMKV (with timestamp)
          try {
            storage.set('suggestedNextCase', JSON.stringify(newSuggestedCase));
          } catch (error) {
            console.warn('Error persisting suggested case:', error);
          }
        }
      }
    }
  }, [shouldShowSuggestedCase, progressStatus, departmentProgress, suggestedNextCase, isPremium, storage]);

  // Function to clear suggested case (call this when user completes the case)
  const clearSuggestedCase = useCallback(() => {
    setSuggestedNextCase(null);
    try {
      storage.delete('suggestedNextCase');
    } catch (error) {
      console.warn('Error clearing suggested case:', error);
    }
  }, [storage]);

  // Check if the suggested case was completed when screen regains focus
  useFocusEffect(
    useCallback(() => {
      const checkIfSuggestedCaseCompleted = async () => {
        if (!suggestedNextCase?.caseId || !currentUserId) return;

        try {
          // Check if there's a completed gameplay for this specific case
          const res = await fetch(
            `${API_BASE}/api/gameplays?userId=${encodeURIComponent(currentUserId)}&caseId=${encodeURIComponent(suggestedNextCase.caseId)}&sourceType=case`
          );

          if (!res.ok) return;

          const data = await res.json();
          const gameplays = data?.gameplays || [];
          const completedGameplay = gameplays.find(gp => gp.status === 'completed');

          if (completedGameplay) {
            clearSuggestedCase();
          }
        } catch (error) {
          console.warn('Error checking suggested case completion:', error);
        }
      };

      checkIfSuggestedCaseCompleted();
    }, [suggestedNextCase?.caseId, currentUserId, clearSuggestedCase])
  );

  // Refresh lifetime offer card visibility on focus
  useFocusEffect(
    useCallback(() => {
      try {
        const storedStart = storage.getNumber('lifetimeOfferStartTime') || 0;
        const startTime = getCurrentLifetimeOfferStart(storedStart);
        const wasDismissed = storage.getBoolean('lifetimeOfferDismissed');
        if (startTime && wasDismissed) {
          if (startTime !== storedStart) {
            storage.set('lifetimeOfferStartTime', startTime);
          }
          setOfferStartTime(startTime);
        } else {
          setOfferStartTime(null);
        }
      } catch {}
    }, [storage])
  );

  const openCaseById = async (caseId, entryPoint = 'home') => {
    try {
      if (isFreeCaseLimitReached) {
        trackEvent('free_case_limit_reached', {
          case_id: caseId,
          entry_point: entryPoint,
          source_type: 'case',
          is_premium: isPremium,
        });
        navigation.navigate('Premium', { source: 'case_limit', caseId });
        return;
      }

      trackEvent('case_started', {
        case_id: caseId,
        entry_point: entryPoint,
        source_type: 'case',
        is_premium: isPremium,
      });
      dispatch(clearCurrentGame()); // Clear old data to prevent stale flash
      navigation.navigate('ClinicalInfo');
      await dispatch(loadCaseById(caseId));
    } catch (_) { }
  };

  // Handle daily challenge press - check if already completed
  const handleDailyChallengePress = async () => {
    if (!currentChallenge?._id || !currentUserId) {
      return;
    }

    setIsDailyChallengeLoading(true);

    try {
      // Check if there's an existing gameplay for this daily challenge
      const res = await fetch(
        `${API_BASE}/api/gameplays?userId=${encodeURIComponent(currentUserId)}&dailyChallengeId=${encodeURIComponent(currentChallenge._id)}&sourceType=dailyChallenge`
      );

      if (!res.ok) {
        throw new Error('Failed to check gameplay status');
      }

      const data = await res.json();
      const gameplays = data?.gameplays || [];
      const completedGameplay = gameplays.find(gp => gp.status === 'completed');

      if (completedGameplay) {
        // Already completed - load selections and navigate to ClinicalInsight
        const caseData = currentChallenge?.caseData || {};

        // Map indices -> IDs for selections
        const tests = caseData?.steps?.[1]?.data?.availableTests || [];
        const diags = caseData?.steps?.[2]?.data?.diagnosisOptions || [];
        const step4 = caseData?.steps?.[3]?.data || {};
        const treatmentGroups = step4?.treatmentOptions || {};
        const flatTreatments = [
          ...(treatmentGroups.medications || []),
          ...(treatmentGroups.surgicalInterventional || []),
          ...(treatmentGroups.nonSurgical || []),
          ...(treatmentGroups.psychiatric || []),
        ];

        const selectedTestIds = (completedGameplay?.selections?.testIndices || [])
          .map((i) => (typeof i === 'number' && tests[i] ? tests[i].testId : null))
          .filter(Boolean);
        const selectedDiagnosisId = (typeof completedGameplay?.selections?.diagnosisIndex === 'number' && diags[completedGameplay.selections.diagnosisIndex])
          ? diags[completedGameplay.selections.diagnosisIndex].diagnosisId
          : null;
        const selectedTreatmentIds = (completedGameplay?.selections?.treatmentIndices || [])
          .map((i) => (typeof i === 'number' && flatTreatments[i] ? flatTreatments[i].treatmentId : null))
          .filter(Boolean);

        // Set case data and selections in Redux
        dispatch(setCaseData({
          dailyChallengeId: currentChallenge?._id,
          caseData: caseData,
          sourceType: 'dailyChallenge'
        }));
        dispatch(setSelectedTests(selectedTestIds));
        dispatch(setSelectedDiagnosis(selectedDiagnosisId));
        dispatch(setSelectedTreatments(selectedTreatmentIds));
        dispatch(setGameplay(completedGameplay));

        // Navigate to ClinicalInsight to review the completed case
        trackEvent('daily_challenge_insights_viewed', {
          daily_challenge_id: currentChallenge?._id,
          source_type: 'dailyChallenge',
          is_premium: isPremium,
        });
        navigation.navigate('ClinicalInsight', { caseData, from: 'HomeScreen' });

        ToastAndroid.show('You\'ve already completed today\'s challenge!', ToastAndroid.SHORT);
      } else {
        // Not completed - proceed with normal flow
        if (isFreeCaseLimitReached) {
          navigation.navigate('Premium', {
            source: 'case_limit',
            dailyChallengeId: currentChallenge?._id,
          });
          return;
        }

        trackEvent('daily_challenge_started', {
          daily_challenge_id: currentChallenge?._id,
          entry_point: 'home',
          source_type: 'dailyChallenge',
          is_premium: isPremium,
        });
        dispatch(setCaseData({
          dailyChallengeId: currentChallenge?._id,
          caseData: currentChallenge?.caseData,
          sourceType: 'dailyChallenge'
        }));
        navigation.navigate('ClinicalInfo');
      }
    } catch (error) {
      console.warn('Error checking daily challenge status:', error);
    } finally {
      setIsDailyChallengeLoading(false);
    }
  };

  return (
    <SafeAreaView style={styles.flex1} edges={['top', 'left', 'right']}>
      <LeagueHeader onPressPro={() => { }} />
      <ScrollView contentContainerStyle={styles.screenScroll} showsVerticalScrollIndicator={false}>
        {/* Lifetime offer card — shown after the two-case limit and after the exit offer is dismissed */}
        {!isPremium && isFreeCaseLimitReached && offerStartTime && (
          <LifetimeOfferCard
            offerStartTime={offerStartTime}
            onOfferExpired={handleOfferExpired}
          />
        )}
        {shouldShowDailyChallengeCard && (
          <View style={[styles.card, { backgroundColor: themeColors.card, borderColor: themeColors.border }]}>
            <View style={styles.cardContent}>
              <View style={styles.rowCenterBetween}>
                <View style={styles.rowCenter}>
                  <Image source={calendarIcon} style={{ width: 40, height: 40, resizeMode: 'contain' }} />
                  <Text style={[styles.cardTitle, { marginLeft: 8, color: themeColors.text }]}>{t('home.dailyChallenge')}</Text>
                </View>
                {!isCheckingCompletion && !isChallengeLoading && (
                  <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                    <TouchableOpacity
                      onPress={() => navigation.navigate('PastChallenges')}
                      style={{
                        flexDirection: 'row',
                        alignItems: 'center',
                        paddingHorizontal: 10,
                        paddingVertical: 6,
                      }}
                      activeOpacity={0.7}
                    >
                      <MaterialCommunityIcons name="history" size={20} color={Colors.brand.darkPink} />
                      <Text style={{ marginLeft: 5, color: Colors.brand.darkPink, fontSize: 15, fontWeight: '700' }}>{t('home.history')}</Text>
                    </TouchableOpacity>
                  </View>
                )}
              </View>

              {(isChallengeLoading || isCheckingCompletion) && <Skeleton.DailyChallenge imageHeight={imageHeight} />}

              {hasChallengeError && !isChallengeLoading && (
                <View style={{ marginTop: 8 }}>
                  <Text style={[styles.cardDesc, { color: '#C62828' }]}>
                    {challengeError || 'Failed to load today\'s challenge'}
                  </Text>

                </View>
              )}

              {currentChallenge && !isChallengeLoading && !isCheckingCompletion && !hasChallengeError && (
                <>
                  {isDailyChallengeCompleted ? (
                    <View style={{ marginTop: 8 }}>
                      <Text style={[styles.cardDesc, { fontSize: 15, color: '#2E7D32', marginTop: 0 }]}>
                        {t('home.challengeCompleted')}
                      </Text>
                      <TouchableOpacity
                        onPress={handleDailyChallengePress}
                        disabled={isDailyChallengeLoading}
                        style={{ marginTop: 12, flexDirection: 'row', alignItems: 'center', justifyContent: 'center' }}
                      >
                        {isDailyChallengeLoading ? (
                          <ActivityIndicator size="small" color={Colors.brand.darkPink} />
                        ) : (
                          <Text style={{ color: Colors.brand.darkPink, fontWeight: '800', fontSize: 15 }}>
                            {t('home.viewInsights')}
                          </Text>
                        )}
                      </TouchableOpacity>
                    </View>
                  ) : (
                    <>
                      {currentChallenge?.caseData?.mainimage && (
                        <View style={{ width: '100%', height: imageHeight, borderRadius: 16, overflow: 'hidden', backgroundColor: '#F5F5F5' }}>
                          <Image
                            source={{ uri: currentChallenge?.caseData?.mainimage }}
                            style={{ width: '100%', height: '100%', resizeMode: 'cover' }}
                          />
                          {/* Gradient overlay */}
                          <LinearGradient
                            colors={['transparent', 'rgba(0,0,0,0.85)']}
                            style={{
                              position: 'absolute',
                              bottom: 0,
                              left: 0,
                              right: 0,
                              height: imageHeight * 0.6,
                            }}
                          />
                          {/* Text positioned absolutely at bottom */}
                          <View style={{
                            position: 'absolute',
                            bottom: 0,
                            left: 0,
                            right: 0,
                            paddingHorizontal: 16,
                            paddingBottom: 14,
                          }}>
                            <Text style={{
                              fontFamily: 'Artifika-Regular',
                              fontSize: 18,
                              color: 'white',
                              fontWeight: '600',
                            }} numberOfLines={2}>
                              {currentChallenge?.caseData?.caseTitle || 'Solve today\'s case in under 3 tries to keep your streak alive.'}
                            </Text>
                          </View>
                        </View>
                      )}
                      {!currentChallenge?.caseData?.mainimage && (
                        <Text style={[styles.cardDesc, { marginTop: 8, fontFamily: 'Artifika-Regular', fontSize: 18, color: "black" }]}>
                          {currentChallenge?.caseData?.caseTitle || 'Solve today\'s case in under 3 tries to keep your streak alive.'}
                        </Text>
                      )}
                      <TouchableOpacity
                        style={[styles.primaryButton, isDailyChallengeLoading && { opacity: 0.7 }]}
                        activeOpacity={0.9}
                        onPress={handleDailyChallengePress}
                        disabled={isDailyChallengeLoading}
                      >
                        {isDailyChallengeLoading ? (
                          <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                            <ActivityIndicator color="#FFFFFF" size="small" />
                            <Text style={styles.primaryButtonText}>{t('home.solveChallenge')}</Text>
                          </View>
                        ) : (
                          <Text style={styles.primaryButtonText}>{t('home.solveChallenge')}</Text>
                        )}
                      </TouchableOpacity>
                    </>
                  )}
                </>
              )}
            </View>
          </View>
        )}

        {/* Continue Solving Card - Shows when daily challenge is completed OR no challenge available */}
        {shouldShowSuggestedCase && suggestedNextCase && (
          <View style={[styles.card, { backgroundColor: themeColors.card, borderColor: themeColors.border, marginTop: 5 }]}>
            <View style={styles.cardContent}>
              <View style={styles.rowCenterBetween}>
                <View style={styles.rowCenter}>
                  <MaterialCommunityIcons name="medical-bag" size={28} color={Colors.brand.darkPink} />
                  <Text style={[styles.cardTitle, { marginLeft: 8, color: themeColors.text }]}>{t('home.solveTheCase')}</Text>
                </View>
                <View style={{
                  alignSelf: 'flex-start',
                  paddingHorizontal: 8,
                  paddingVertical: 3,
                  borderRadius: 6,
                  backgroundColor: '#C24467',
                  borderWidth: 1,
                  borderColor: '#D3D9E3'
                }}>
                  <Text style={{ fontSize: 10.5, fontWeight: '800', color: '#ffffff' }} numberOfLines={1} ellipsizeMode="tail">
                    {suggestedNextCase.departmentName.charAt(0).toUpperCase() + suggestedNextCase.departmentName.slice(1)}
                  </Text>
                </View>
              </View>

              {suggestedNextCase.mainimage ? (
                <View style={{ width: '100%', height: imageHeight, backgroundColor: '#F5F5F5', borderRadius: 16, overflow: 'hidden', marginTop: 12 }}>
                  <Image
                    source={{ uri: suggestedNextCase.mainimage }}
                    style={{ width: '100%', height: '100%', resizeMode: 'cover' }}
                  />
                  {/* Gradient overlay */}
                  <LinearGradient
                    colors={['transparent', 'rgba(0,0,0,0.85)']}
                    style={{
                      position: 'absolute',
                      bottom: 0,
                      left: 0,
                      right: 0,
                      height: imageHeight * 0.6,
                    }}
                  />
                  {/* Text positioned absolutely at bottom */}
                  <View style={{
                    position: 'absolute',
                    bottom: 0,
                    left: 0,
                    right: 0,
                    paddingHorizontal: 16,
                    paddingBottom: 14,
                  }}>
                    <Text style={{
                      fontSize: 18,
                      fontFamily: 'Artifika-Regular',
                      color: 'white',
                      fontWeight: '600',
                    }} numberOfLines={2}>
                      {suggestedNextCase.caseTitle}
                    </Text>
                  </View>
                </View>
              ) : (
                <Text style={[styles.cardDesc, { marginTop: 12, fontSize: 18, fontFamily: 'Artifika-Regular', color: "black" }]} numberOfLines={2}>
                  {suggestedNextCase.caseTitle}
                </Text>
              )}

              <TouchableOpacity
                style={styles.primaryButton}
                activeOpacity={0.9}
                onPress={() => {
                  if (isFreeCaseLimitReached || suggestedNextCase.isPremiumCase) {
                    trackEvent('premium_screen_opened', {
                      trigger: 'suggested_case_locked',
                      case_id: suggestedNextCase.caseId,
                      source_type: 'case',
                      is_premium: isPremium,
                    });
                    navigation.navigate('Premium', {
                      source: suggestedNextCase.isPremiumCase ? 'premium_case' : 'case_limit',
                      caseId: suggestedNextCase.caseId,
                    });
                  } else {
                    openCaseById(suggestedNextCase.caseId, 'suggested_case');
                  }
                }}
              >
                <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                  {suggestedNextCase.isPremiumCase && (
                    <MaterialCommunityIcons name="lock" size={16} color="#FFFFFF" style={{ marginRight: 6 }} />
                  )}
                  <Text style={styles.primaryButtonText}>
                    {suggestedNextCase.isPremiumCase
                      ? t('home.unlockPremium')
                      : t('home.solveTheCase')}
                  </Text>
                </View>
              </TouchableOpacity>
            </View>
          </View>
        )}

        <View style={{ marginBottom: 120 }}>
          <View style={styles.rowCenterBetween}>
            <View style={styles.rowCenter}>
              <Image source={departmentIcon} style={{ width: 40, height: 40, resizeMode: 'contain' }} />
              <Text style={[styles.cardTitle, { marginLeft: 8, color: themeColors.text }]}>{t('home.departments')}</Text>
            </View>
          </View>
          {categoriesLoading === 'loading' && <Skeleton.DepartmentsList />}
          {categoriesError && categoriesLoading !== 'loading' && (
            <Text style={[styles.cardDesc, { color: '#C62828', marginTop: 8 }]}>{categoriesError}</Text>
          )}
          {categoriesLoading !== 'loading' && !categoriesError && (
            <DepartmentProgressList
              userId={currentUserId}
              themeColors={themeColors}
              onStartCase={openCaseById}
            />
          )}
        </View>


        <CloudBottom height={160} bottomOffset={insets?.bottom + 56} color={"#FF407D"} style={{ opacity: 0.35 }} />
      </ScrollView>
    </SafeAreaView>
  );
}
